<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Laporan Bansos {{ $year }}</title><style>body{font:10pt Arial;padding:1.5cm}.header{text-align:center;border-bottom:2px solid #000;padding-bottom:8px}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{border:1px solid #333;padding:5px}th{background:#eee}.right{text-align:right}@media print{.no-print{display:none}}</style></head><body><div class="no-print"><button onclick="print()">Cetak</button></div><div class="header"><h3>PEMERINTAH DESA {{ strtoupper($village->name ?? 'DESA') }}</h3><h4>REKAPITULASI PROGRAM BANTUAN TAHUN {{ $year }}</h4></div>@foreach($programs as $p)<h4>{{ $p->code }} — {{ $p->name }}</h4><p>Kuota: {{ $p->quota }} | Terdaftar: {{ $p->recipients_count }} | Nominal/Penerima: Rp {{ number_format($p->budget_per_recipient,0,',','.') }}</p><table><tr><th>No</th><th>NIK</th><th>Nama</th><th>Status</th><th>Tanggal Salur</th><th>Referensi</th><th>Nominal</th></tr>@foreach($p->recipients as $i=>$r)<tr><td>{{ $i+1 }}</td><td>{{ $r->citizen->nik ?? '-' }}</td><td>{{ $r->citizen->name ?? '-' }}</td><td>{{ $r->status }}</td><td>{{ optional($r->distribution_date)->format('d/m/Y') }}</td><td>{{ $r->distribution_reference ?? '-' }}</td><td class="right">Rp {{ number_format($r->amount_received,0,',','.') }}</td></tr>@endforeach</table>@endforeach</body></html>